public class InnerRegistryRecordDescriptorsFactory(Action<Humidifier.AgentRegistry.RegistryRecordTypes.Descriptors> factoryAction = null) : SubResourceFactory<Humidifier.AgentRegistry.RegistryRecordTypes.Descriptors>
{

    internal InnerRegistryRecordAgentSkillsDefinitionDescriptorFactory AgentSkillsDefinitionFactory { get; set; }

    internal InnerRegistryRecordA2aAgentCardDescriptorFactory A2aAgentCardFactory { get; set; }

    internal InnerRegistryRecordAgUiDescriptorFactory AguiFactory { get; set; }

    internal InnerRegistryRecordMcpServerDescriptorFactory McpServerFactory { get; set; }

    internal InnerRegistryRecordCustomDescriptorFactory CustomFactory { get; set; }

    internal InnerRegistryRecordHttpDescriptorFactory HttpFactory { get; set; }

    protected override Humidifier.AgentRegistry.RegistryRecordTypes.Descriptors Create()
    {
        var descriptorsResult = CreateDescriptors();
        factoryAction?.Invoke(descriptorsResult);

        return descriptorsResult;
    }

    private Humidifier.AgentRegistry.RegistryRecordTypes.Descriptors CreateDescriptors()
    {
        var descriptorsResult = new Humidifier.AgentRegistry.RegistryRecordTypes.Descriptors();

        return descriptorsResult;
    }
    public override void CreateChildren(Humidifier.AgentRegistry.RegistryRecordTypes.Descriptors result)
    {
        base.CreateChildren(result);

        result.AgentSkillsDefinition ??= AgentSkillsDefinitionFactory?.Build();
        result.A2aAgentCard ??= A2aAgentCardFactory?.Build();
        result.Agui ??= AguiFactory?.Build();
        result.McpServer ??= McpServerFactory?.Build();
        result.Custom ??= CustomFactory?.Build();
        result.Http ??= HttpFactory?.Build();
    }

} // End Of Class

